import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

// Дешёвая модель читает объём: на входе сырая страница, на выходе короткая выжимка
export async function distill(page: string, question: string): Promise<string> {
  const msg = await client.messages.create({
    model: "claude-haiku-4-5",
    max_tokens: 800,
    messages: [{
      role: "user",
      content:
        "Research question: " + question +
        "\n\nFrom the page below, extract only the facts relevant to the question, " +
        "as short bullet points, each with the source sentence quoted.\n\n<page>\n" + page + "\n</page>",
    }],
  });
  return msg.content.flatMap((b) => (b.type === "text" ? [b.text] : [])).join("");
}
// Дорогая модель (Sonnet) получает эту выжимку как результат инструмента, сырую страницу никогда.

import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

// $ за MTok, переписано со страницы pricing: сверь перед использованием
const PRICE = {
  "claude-sonnet-5": { in: 2, out: 10 },
  "claude-haiku-4-5": { in: 1, out: 5 },
} as const;
type ModelId = keyof typeof PRICE;

// Один пример golden set: вход и факты, которые хорошая выжимка обязана сохранить
type Case = { page: string; question: string; mustKeep: string[] };

async function distillWith(model: ModelId, c: Case) {
  const msg = await client.messages.create({
    model,
    max_tokens: 800,
    messages: [{ role: "user", content: "Question: " + c.question + "\nExtract the relevant facts as bullet points.\n\n" + c.page }],
  });
  const text = msg.content.flatMap((b) => (b.type === "text" ? [b.text] : [])).join("");
  // реальная стоимость вызова из usage (цифры, по которым выставляют счёт)
  const cost = (msg.usage.input_tokens * PRICE[model].in + msg.usage.output_tokens * PRICE[model].out) / 1e6;
  return { text, cost };
}

export async function compare(golden: Case[]) {
  for (const model of Object.keys(PRICE) as ModelId[]) {
    let kept = 0, total = 0, cost = 0;
    for (const c of golden) {
      const r = await distillWith(model, c);
      cost += r.cost;
      for (const fact of c.mustKeep) {
        total++;
        if (r.text.toLowerCase().includes(fact.toLowerCase())) kept++;
      }
    }
    console.log(model, "facts kept:", (kept / total).toFixed(2), "cost: $" + cost.toFixed(4));
  }
}

